{
  "name": "large_gambling_or_crypto EarlyMorning",
  "description": "Detects large gambling or crypto transactions over $800 in the early hours of the morning.",
  "severity": "high",
  "action": "flag",
  "logic": "all",
  "conditions": [
    {"field": "merchant_category", "op": "in", "value": ["gambling", "crypto"]},
    {"field": "amount", "op": ">", "value": 800},
    {"field": "hour_of_day", "op": "between", "value": [0, 6]}
  ],
  "rationale": "Large transactions in gambling or crypto categories during early morning hours are indicative of potential fraudulent activity."
}

{
  "name": "fraud_flag",
